/// On-disk comp setup. snarl carries nodes (params + Read paths), positions
/// and wires; the rest is the light app state worth keeping.
#[derive(serde::Serialize, Clone)]
struct SetupSave<'a> {
    version: u32,
    fps: f32,
    pinned_dirs: &'a Vec<std::path::PathBuf>,
    graph: &'a EditorGraph,
    canvas: Option<(u32, u32)>,
    range: Option<(u64, u64)>,
    /// Extra frames either side of the script range, for retimes and filters
    /// that need to reach past the cut.
    handles: (u64, u64),
    /// Playback in/out, a sub-range of the script you are working inside.
    play_range: Option<(u64, u64)>,
    /// The viewer range pinned by hand (`None` = follow the viewed noodle).
    view_range: Option<(u64, u64)>,
    loop_span: LoopSpan,
    /// The SCRIPT's own control panel size, in whole tiles. A comp that
    /// exports to an edit has a panel like a tool's; this is its grid.
    panel: Option<(usize, usize)>,
    huds: &'a Vec<widgets::HudSlider>,
    activated: &'a Vec<u64>,
    pinned_gizmos: &'a Vec<u64>,
    prop_layouts: &'a Vec<PropLayout>,
    patch_tiles: Vec<(u64, [i32; 2], [u8; 2])>,
    /// Saved channel sets, shared by the curve editor and dope sheet.
    #[serde(skip_serializing_if = "<[_]>::is_empty")]
    chan_sets: &'a [chanview::ChanSet],
}

#[derive(serde::Deserialize)]
struct SetupLoad {
    #[allow(dead_code)]
    version: u32,
    fps: f32,
    #[serde(default)]
    pinned_dirs: Vec<std::path::PathBuf>,
    graph: EditorGraph,
    #[serde(default)]
    canvas: Option<(u32, u32)>,
    #[serde(default)]
    range: Option<(u64, u64)>,
    #[serde(default)]
    handles: (u64, u64),
    #[serde(default)]
    play_range: Option<(u64, u64)>,
    /// The viewer range pinned by hand; absent = follow the viewed noodle.
    #[serde(default)]
    view_range: Option<(u64, u64)>,
    #[serde(default)]
    loop_span: LoopSpan,
    #[serde(default)]
    panel: Option<(usize, usize)>,
    #[serde(default)]
    huds: Vec<widgets::HudSlider>,
    #[serde(default)]
    activated: Vec<u64>,
    #[serde(default)]
    pinned_gizmos: Vec<u64>,
    #[serde(default)]
    prop_layouts: Vec<PropLayout>,
    #[serde(default)]
    patch_tiles: Vec<(u64, [i32; 2], [u8; 2])>,
    #[serde(default)]
    chan_sets: Vec<chanview::ChanSet>,
}

/// Cached render frames record what the fused pass produced. Bump when that
/// meaning changes so stale bakes miss instead of replaying wrong pixels.
const COMP_FORMAT_GENERATION: u32 = 3;

/// A Bake made under proxy sits beside its full-res bake, named by the same
/// key plus this (`Gfx::graph_bake_proxy_dir`).
const PROXY_BAKE_SUFFIX: &str = "-proxy2";

/// Is this loaded bake path a proxy bake?
fn is_proxy_bake(path: &str) -> bool {
    path.trim_end_matches(['/', '\\']).ends_with(PROXY_BAKE_SUFFIX)
}

/// What the vector HUD draws over a 2dini's render — Houdini's display
/// options, one toggle each on the viewer's display bar.
#[derive(serde::Serialize, serde::Deserialize, Clone, Copy, PartialEq, Debug)]
#[serde(default)]
struct GeoViz {
    /// Every point as a dot.
    points: bool,
    /// Each point's index beside it.
    point_nums: bool,
    /// Each shape's index at its centre.
    prim_nums: bool,
    /// Outline normals.
    normals: bool,
    /// Each point's orientation (what an Instance turns a copy by).
    ticks: bool,
    /// Shape outlines (Houdini's wireframe).
    outlines: bool,
    /// The geometry's bounding box.
    bbox: bool,
    /// Rulers along the image's top and left edges, in output pixels.
    rulers: bool,
    /// Handles and drawing tools snap: to another shape's centre when one
    /// is near, else to the rulers' fine ticks. Ctrl held lets go.
    snap: bool,
    /// Onion skins: the drawing's outlines `onion_before` / `onion_after`
    /// steps either side of the playhead, `onion_step` frames apart, each
    /// step fainter by `onion_falloff`.
    onion: bool,
    onion_before: u32,
    onion_after: u32,
    onion_step: u32,
    onion_falloff: f32,
}

impl Default for GeoViz {
    fn default() -> Self {
        Self {
            points: true,
            point_nums: false,
            prim_nums: false,
            normals: true,
            ticks: true,
            outlines: true,
            bbox: false,
            rulers: false,
            snap: false,
            onion: false,
            onion_before: 2,
            onion_after: 2,
            onion_step: 1,
            onion_falloff: 0.55,
        }
    }
}

